-- Semantic search: pgvector + a 384-dim embedding per product.
-- Embeddings are generated by the `semantic-search` Edge Function using
-- Supabase's built-in gte-small model (no external API needed).

create extension if not exists vector with schema extensions;

alter table public.products
  add column if not exists embedding extensions.vector(384);

-- gte-small embeddings are normalized, so inner product == cosine similarity
-- and is faster to compute.
create index if not exists products_embedding_hnsw
  on public.products using hnsw (embedding vector_ip_ops);

-- Match products by embedding similarity. SECURITY INVOKER: runs under the
-- caller's role, so the public-read RLS policy on products applies.
create or replace function public.match_products (
  query_embedding extensions.vector(384),
  match_threshold float default 0.7,
  match_count int default 8
)
returns setof public.products
language sql
security invoker
set search_path = ''
as $$
  select *
  from public.products
  where products.embedding is not null
    -- inner product is negative, so negate the threshold. The operator is
    -- schema-qualified because the function pins an empty search_path.
    and products.embedding operator(extensions.<#>) query_embedding < -match_threshold
  order by products.embedding operator(extensions.<#>) query_embedding
  limit least(match_count, 50);
$$;
